CREATE TABLE inventory_planning_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,item_id uuid NOT NULL,location_id uuid NOT NULL,safety_stock numeric(18,6) NOT NULL DEFAULT 0,lead_time_days integer NOT NULL DEFAULT 7 CHECK(lead_time_days BETWEEN 0 AND 365),forecast_horizon_days integer NOT NULL DEFAULT 14 CHECK(forecast_horizon_days IN(1,7,14,30)),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,item_id,location_id),FOREIGN KEY(company_id,item_id) REFERENCES items(company_id,id),FOREIGN KEY(company_id,location_id) REFERENCES locations(company_id,id));
CREATE TABLE replenishment_recommendations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,item_id uuid NOT NULL,from_location_id uuid NOT NULL,to_location_id uuid NOT NULL,recommended_quantity numeric(18,6) NOT NULL CHECK(recommended_quantity>0),average_daily_usage numeric(18,6) NOT NULL,open_demand numeric(18,6) NOT NULL,days_of_cover numeric(18,2),projected_stockout_date date,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected','converted')),created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz,reviewed_by uuid REFERENCES users(id),review_note text,replenishment_task_id uuid REFERENCES replenishment_tasks(id),FOREIGN KEY(company_id,item_id) REFERENCES items(company_id,id),FOREIGN KEY(company_id,from_location_id) REFERENCES locations(company_id,id),FOREIGN KEY(company_id,to_location_id) REFERENCES locations(company_id,id));
ALTER TABLE inventory_planning_rules ENABLE ROW LEVEL SECURITY;ALTER TABLE inventory_planning_rules FORCE ROW LEVEL SECURITY;ALTER TABLE replenishment_recommendations ENABLE ROW LEVEL SECURITY;ALTER TABLE replenishment_recommendations FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_inventory_planning_rules ON inventory_planning_rules USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);CREATE POLICY tenant_replenishment_recommendations ON replenishment_recommendations USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);GRANT SELECT,INSERT,UPDATE,DELETE ON inventory_planning_rules,replenishment_recommendations TO stockflow_app;CREATE INDEX replenishment_recommendations_status_idx ON replenishment_recommendations(company_id,status,created_at DESC);
